
CREATE TABLE purchases (
    id INT,
    order_date DATE,
    order_id INT,
    customer_id INT,
    product_id INT,
    category TEXT,
    subcategory TEXT,
    product_type TEXT,
    membership_type TEXT,
    promotion TEXT,
    gross_price DECIMAL(10,2),
    net_price DECIMAL(10,2),
    cost_price DECIMAL(10,2),
    quantity INT
);




